package com.thang.user.security;
import com.thang.user.UserServiceApplication;import com.thang.user.model.entity.*;import com.thang.user.model.dto.LoginRequest;import com.thang.user.repository.*;import com.thang.user.service.user.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.util.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import com.fasterxml.jackson.databind.ObjectMapper;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(classes=UserServiceApplication.class,webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.config.import=","spring.datasource.url=jdbc:h2:mem:account_features;MODE=MySQL;NON_KEYWORDS=USER;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=create-drop","spring.jpa.properties.hibernate.dialect=org.hibernate.dialect.H2Dialect","eureka.client.enabled=false","spring.cloud.discovery.enabled=false","spring.kafka.admin.auto-create=false","auth.activation-outbox.enabled=false","security.jwt.mode=rsa","security.jwt.validate-claims=true","security.session-validation.enabled=true","security.origin-check.enabled=true","COOKIE_SECURE=false"})
class AccountFeaturesIntegrationTest {
 @Autowired IUserRepository users;@Autowired PasswordEncoder passwords;@Autowired AuthMfaService mfa;@Autowired AuthMfaDeviceRepository devices;@Autowired AuthMfaChallengeRepository challenges;@Autowired AuthMfaBackupRepository backups;@Autowired LoginAuditRepository history;@Autowired AccountProfileService profiles;@Autowired AccountRecoveryService recovery;@Autowired PasswordRecoveryRepository tickets;@Autowired AuthActivationOutboxRepository mail;@Autowired SessionTokenCipher cipher;@Autowired IUserService login;@Autowired SessionService sessions;@Autowired AuthSessionRepository sessionRows;@Autowired AuthRateBucketRepository limits;@Autowired PlatformTransactionManager transactions;@Autowired TokenService tokens;
 @MockitoBean KafkaTemplate<String,Object> kafka;@Value("${local.server.port}") int port;
 User user;String password="Strong1!pass";ObjectMapper json=new ObjectMapper();
 @BeforeEach void clean(){challenges.deleteAll();backups.deleteAll();devices.deleteAll();tickets.deleteAll();mail.deleteAll();history.deleteAll();sessionRows.deleteAll();limits.deleteAll();users.deleteAll();user=new User();user.setUserId(UUID.randomUUID().toString());user.setEmail("account-features@example.test");user.setFirstName("Account");user.setLastName("Features");user.setRoleName("STAFF");user.setActive(true);user.setPassword(passwords.encode(password));users.saveAndFlush(user);}
 LoginRequest request(){var r=new LoginRequest();r.setEmail(user.getEmail());r.setPassword(password);return r;}
 String enable(){String secret=TotpCodes.secret();var device=new AuthMfaDevice();device.setUserId(user.getUserId());device.setEnabled(true);device.setEncryptedSecret(cipher.encrypt(user.getUserId(),secret));devices.saveAndFlush(device);return secret;}
 @Test void mfaChallengeCommitsWithoutIssuingAccessBeforeOtpVerification(){String secret=enable();var challenge=assertThrows(MfaRequiredException.class,()->login.login(request())).challenge();assertEquals(1,challenges.count());assertNull(sessions.getSession(user.getUserId()));var result=mfa.verify(challenge,TotpCodes.code(secret,System.currentTimeMillis()/30000));assertNotNull(result.tokens());assertEquals(1,history.count());assertNull(mfa.verify(challenge,TotpCodes.code(secret,System.currentTimeMillis()/30000)).tokens());}
 @Test void wrongOtpAttemptsCommitAndBackupCodesAreSingleUse(){String secret=enable();var c=assertThrows(MfaRequiredException.class,()->login.login(request())).challenge();for(int i=0;i<5;i++)assertNull(mfa.verify(c,"not-a-code").tokens());assertEquals(0,challenges.count());limits.deleteAll();var device=devices.findById(user.getUserId()).orElseThrow();device.setLastCounter(-1);devices.saveAndFlush(device);String code=TotpCodes.code(secret,System.currentTimeMillis()/30000);var list=mfa.newBackups(user.getUserId(),password,code);assertEquals(10,list.size());assertEquals(10,backups.count());var challenge=assertThrows(MfaRequiredException.class,()->login.login(request())).challenge();assertNotNull(mfa.verify(challenge,list.get(0)).tokens());assertEquals(9,backups.count());var next=assertThrows(MfaRequiredException.class,()->login.login(request())).challenge();assertNull(mfa.verify(next,list.get(0)).tokens());}
 @Test void recoveryUsesEncryptedOutboxSingleUseTokenAndRevokesSessions()throws Exception{tokens.generateToken(user,"sid-1");recovery.request(user.getEmail());assertEquals(1,tickets.count());assertEquals(1,mail.count());var envelope=mail.findAll().get(0);var payload=json.readTree(cipher.decrypt(user.getUserId(),envelope.getEncryptedPayload()));assertEquals("PASSWORD_RESET",payload.get("purpose").asText());String token=payload.get("recoveryToken").asText(),id=payload.get("recoveryId").asText();assertFalse(envelope.getEncryptedPayload().contains(token));var input=new AccountRecoveryService.Reset(id,token,"Changed2!pass","Changed2!pass");recovery.reset(input);assertNull(sessions.getSession(user.getUserId()));assertTrue(passwords.matches("Changed2!pass",users.findById(user.getUserId()).orElseThrow().getPassword()));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->recovery.reset(input));}
 @Test void unknownOrInactiveEmailDoesNotEnqueueAndOldPasswordInvalidatesChallenges(){recovery.request("unknown@example.test");assertEquals(0,tickets.count());String secret=enable();var challenge=assertThrows(MfaRequiredException.class,()->login.login(request())).challenge();profiles.changePassword(user.getUserId(),new AccountProfileService.ChangePassword(password,"Changed2!pass","Changed2!pass"));assertNull(mfa.verify(challenge,TotpCodes.code(secret,System.currentTimeMillis()/30000)).tokens());}
 @Test void profileCannotChangeEmailAndLoginApiSetsOnlyChallengeCookieBeforeMfa()throws Exception{profiles.save(user.getUserId(),new AccountProfileService.Profile("New","Name","attacker@example.test","123",null,null));assertEquals(user.getEmail(),users.findById(user.getUserId()).orElseThrow().getEmail());enable();var response=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/auth/login")).header("Content-Type","application/json").header("Origin","http://localhost:5173").POST(HttpRequest.BodyPublishers.ofString("{\"email\":\""+user.getEmail()+"\",\"password\":\""+password+"\"}")).build(),HttpResponse.BodyHandlers.ofString());assertEquals(202,response.statusCode());var cookies=response.headers().allValues("set-cookie");assertEquals(1,cookies.size());assertTrue(cookies.get(0).startsWith("mfaChallenge="));assertTrue(cookies.get(0).contains("HttpOnly"));assertFalse(response.body().contains("accessToken"));}
 @Autowired com.nihongo.security.InternalCredentials internalCredentials;
 @Test void loginPersistsLanSnapshotAndHistoryReturnsItToTheOwner() throws Exception {
  String signed = new com.nihongo.security.LoginAddressEnvelope(internalCredentials).sign("POST", "/api/auth/login", "127.0.0.1", "192.168.1.8");
  var client = HttpClient.newHttpClient();
  var response = client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + port + "/api/auth/login"))
   .header("Content-Type", "application/json").header("Origin", "http://localhost:5173")
   .header(com.nihongo.security.LoginAddressEnvelope.HEADER, signed)
   .POST(HttpRequest.BodyPublishers.ofString("{\"email\":\"" + user.getEmail() + "\",\"password\":\"" + password + "\"}")).build(), HttpResponse.BodyHandlers.ofString());
  assertEquals(200, response.statusCode());
  var saved = history.findAll().get(0);
  assertEquals("127.0.0.1", saved.getAddress()); assertEquals("192.168.1.8", saved.getLocalAddresses());
  String cookie = response.headers().allValues("set-cookie").stream().filter(c -> c.startsWith("accessToken=")).findFirst().orElseThrow().split(";", 2)[0];
  var auditResponse = client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + port + "/api/users/me/logins"))
   .header("Cookie", cookie).GET().build(), HttpResponse.BodyHandlers.ofString());
  assertEquals(200, auditResponse.statusCode());
  assertEquals("192.168.1.8", json.readTree(auditResponse.body()).get("content").get(0).get("localAddresses").asText());
 }
}
